writing.exampleCode:
fn canonical(mut ids: Vec<i32>) -> Vec<i32> {
    ids.sort_unstable();
    ids.dedup();
    ids
}
fn main() {
    let once = canonical(vec![3, 1, 3]);
    assert_eq!(once, [1, 3]);
    assert_eq!(canonical(once.clone()), once);
}

